import { declOfNum } from '@helpers/formatHelper';

import { HikingJointlyEquipmentType } from '../@types/DTO/hikingJointlyEquipment.dto.types';

export const getHikingJointlyEquipmentNameByType = (
  type: HikingJointlyEquipmentType,
  forCount = 2,
  isGenitive = false,
) => {
  const map: Record<HikingJointlyEquipmentType, [string, string, string]> = {
    tent: ['Палатка', 'Палатки', 'Палаток'],
    watercraft: ['Плавсредство', 'Плавсредства', 'Плавсредств'],
  } as const;

  const genitiveMap: Record<HikingJointlyEquipmentType, [string, string, string]> = {
    tent: ['Палатку', 'Палатки', 'Палаток'],
    watercraft: ['Плавсредство', 'Плавсредства', 'Плавсредств'],
  } as const;
  return declOfNum(forCount, isGenitive ? genitiveMap[type] : map[type]);
};
